<?php
require_once __DIR__.'/_init.php'; require_once __DIR__.'/../includes/admin-ui.php'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'baru';if(!in_array($status,['baru','diproses','diterima','ditolak'],true))$status='baru';$pdo->prepare('UPDATE anggota SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Status anggota diperbarui.');header('Location: anggota.php');exit;}
$rows=$pdo->query('SELECT * FROM anggota ORDER BY created_at DESC')->fetchAll();admin_header('Data Anggota','anggota'); ?>
<section class="panel"><div class="panel-head"><div><h2>Data pendaftar dan anggota</h2><p class="panel-subtitle">Periksa data anggota dan ubah status proses pendaftaran.</p></div></div><?php if(!$rows): ?><div class="empty">Belum ada data anggota di database. Pastikan formulir pendaftaran terhubung ke tabel anggota.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Email</th><th>WhatsApp</th><th>Domisili</th><th>Minat</th><th>Tanggal</th><th>Status</th><th>Simpan</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['nama_lengkap']) ?></td><td><?= e($r['email']??'-') ?></td><td><?= e($r['whatsapp']??'-') ?></td><td><?= e($r['domisili']??'-') ?></td><td><?= e($r['minat_peran']??'-') ?></td><td><?= e($r['created_at']) ?></td><td colspan="2"><form method="post" class="table-actions"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><option value="baru" <?= $r['status']==='baru'?'selected':'' ?>>Baru</option><option value="diproses" <?= $r['status']==='diproses'?'selected':'' ?>>Diproses</option><option value="diterima" <?= $r['status']==='diterima'?'selected':'' ?>>Diterima</option><option value="ditolak" <?= $r['status']==='ditolak'?'selected':'' ?>>Ditolak</option></select><button class="btn btn-sm">Update</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php admin_footer(); ?>